import pandas as pd

def solve(data):
     parts = [pd.DataFrame({'qty':part}) for part in data['batches']]
     combined = pd.concat(parts, ignore_index=True)
     return {'values':combined['qty'].tolist(), 'index':combined.index.tolist()}
